class Solution {
public:
    long long findKthSmallest(vector<int>& coins, int k) {
        int m = coins.size();
        vector<pair<long long, int>> subsets;

        auto gcd = [](long long a, long long b) {
            while (b) { a %= b; swap(a, b); }
            return a;
        };

        for (int mask = 1; mask < (1 << m); ++mask) {
            long long lcm_val = 1;
            int bits = 0;
            for (int i = 0; i < m; ++i) {
                if ((mask >> i) & 1) {
                    bits++;
                    long long g = gcd(lcm_val, coins[i]);
                    lcm_val = (lcm_val / g) * coins[i];
                }
            }
            int sign = (bits % 2 == 1) ? 1 : -1;
            subsets.push_back({lcm_val, sign});
        }

        auto count = [&](long long x) {
            long long total = 0;
            for (const auto& [lcm_val, sign] : subsets) {
                total += sign * (x / lcm_val);
            }
            return total;
        };

        long long low = 1;
        long long min_c = *min_element(coins.begin(), coins.end());
        long long high = min_c * k;
        long long ans = high;

        while (low <= high) {
            long long mid = low + (high - low) / 2;
            if (count(mid) >= k) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
