class Solution {
    public long findKthSmallest(int[] coins, int k) {
        int m = coins.length;
        List<long[]> subsets = new ArrayList<>();

        for (int mask = 1; mask < (1 << m); mask++) {
            long lcmVal = 1;
            int bits = 0;
            for (int i = 0; i < m; i++) {
                if (((mask >> i) & 1) == 1) {
                    bits++;
                    long g = gcd(lcmVal, coins[i]);
                    lcmVal = (lcmVal / g) * coins[i];
                }
            }
            int sign = (bits % 2 == 1) ? 1 : -1;
            subsets.add(new long[]{lcmVal, sign});
        }

        long low = 1;
        long minCoin = Long.MAX_VALUE;
        for (int c : coins) minCoin = Math.min(minCoin, c);
        long high = minCoin * k;
        long ans = high;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (count(subsets, mid) >= k) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private long count(List<long[]> subsets, long x) {
        long total = 0;
        for (long[] s : subsets) {
            total += s[1] * (x / s[0]);
        }
        return total;
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

var findKthSmallest = function(coins, k) {
    const m = coins.length;
    const subsets = [];

    function gcd(a, b) {
        while (b > 0n) {
            let t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    for (let mask = 1; mask < (1 << m); mask++) {
        let lcmVal = 1n;
        let bits = 0;
        for (let i = 0; i < m; i++) {
            if ((mask >> i) & 1) {
                bits++;
                const c = BigInt(coins[i]);
                const g = gcd(lcmVal, c);
                lcmVal = (lcmVal / g) * c;
            }
        }
        const sign = (bits % 2 === 1) ? 1n : -1n;
        subsets.push([lcmVal, sign]);
    }

    function count(x) {
        let total = 0n;
        for (const [lcmVal, sign] of subsets) {
            total += sign * (x / lcmVal);
        }
        return total;
    }

    let minCoin = BigInt(Math.min(...coins));
    let low = 1n;
    let high = minCoin * BigInt(k);
    let ans = high;
    const targetK = BigInt(k);

    while (low <= high) {
        let mid = (low + high) / 2n;
        if (count(mid) >= targetK) {
            ans = mid;
            high = mid - 1n;
        } else {
            low = mid + 1n;
        }
    }
    return Number(ans);
};
